package escuela.personal.service;

import escuela.personal.dto.*;
import escuela.admin.dto.OpcionAutocompletado;
import escuela.common.exception.ReglaNegocioException;
import escuela.finanzas.dto.request.MovimientoManualRequest;
import escuela.finanzas.entity.DireccionMovimiento;
import escuela.finanzas.service.MovimientoManualService;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.data.domain.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class PrestamoEmpleadoService {
 // No habilitar entregas operativas antes de conectar los pagos/abonos individuales.
 @org.springframework.beans.factory.annotation.Value("${app.nomina.prestamos.entrega-habilitada:false}")
 private boolean entregaHabilitada;
 private final EmpleadoService empleados;
 private final ConceptoNominaService conceptos;
 private final NamedParameterJdbcTemplate jdbc;
 private final MovimientoManualService movimientos;
 public record Prestamo(Long id,Long empleadoId,Long conceptoId,Long conceptoVersion,String concepto,BigDecimal importe,BigDecimal parcialidad,String moneda,LocalDate primerDescuento,String estado,String motivo,String gestion,Long version,UUID solicitud,BigDecimal saldo){
  public String folio(){return "PRE-"+String.format(Locale.ROOT,"%06d",id);}
  public BigDecimal cuota(){return saldo.min(parcialidad);}
 }
 public record Concepto(Long id,String texto,Long version){}
 public record Entrega(Long movimientoId,String cuenta,String referencia,String fecha,String usuario,BigDecimal importe,String moneda){}
 public record Historia(String fecha,String usuario,String estado,String motivo){}
 public record Abono(Long pagoId,Long nominaId,Long filaId,String estado,BigDecimal importe,BigDecimal saldoAnterior,BigDecimal saldoPosterior,String fecha){}
 public Page<Abono> abonos(Long emp,Long id,int pagina){obtener(emp,id);var par=p(emp,false).addValue("id",id);var pg=PageRequest.of(Math.max(0,pagina),20);long n=jdbc.queryForObject("SELECT count(*) FROM prestamo_abono_nomina WHERE prestamo_id=:id",par,Long.class);return new PageImpl<>(jdbc.query("SELECT an.*,ni.estado,ne.borrador_id,ne.id fila,to_char(ni.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha FROM prestamo_abono_nomina an JOIN nomina_pago_intento ni ON ni.id=an.pago_id JOIN nomina_borrador_empleado ne ON ne.id=ni.fila_id JOIN institucion i ON i.id=ni.institucion_id WHERE an.prestamo_id=:id AND ni.institucion_id=:inst ORDER BY ni.id DESC LIMIT 20 OFFSET :offset",par.addValue("offset",pg.getOffset()),(r,k)->new Abono(r.getLong("pago_id"),r.getLong("borrador_id"),r.getLong("fila"),r.getString("estado"),r.getBigDecimal("importe"),r.getBigDecimal("saldo_anterior"),r.getBigDecimal("saldo_posterior"),r.getString("fecha"))),pg,n);}
 public record Cuenta(Long id,String texto,String moneda,BigDecimal saldo,Long version){}
 public record Revision(Prestamo prestamo,Cuenta cuenta,String motivoFinanciero,BigDecimal saldoPosterior,String sello){}
 private static final String SELECT="SELECT p.*,s.saldo FROM prestamo_empleado p JOIN prestamo_saldo s ON s.id=p.id ";
 private static final RowMapper<Prestamo> MAP=(r,n)->new Prestamo(r.getLong("id"),r.getLong("empleado_id"),r.getLong("concepto_id"),r.getLong("concepto_version"),r.getString("concepto_codigo")+" · "+r.getString("concepto_nombre"),r.getBigDecimal("importe"),r.getBigDecimal("parcialidad"),r.getString("moneda"),r.getObject("primer_descuento",LocalDate.class),r.getString("estado"),r.getString("motivo"),r.getString("motivo_operacion"),r.getLong("version"),r.getObject("solicitud",UUID.class),r.getBigDecimal("saldo"));
 private MapSqlParameterSource p(Long emp,boolean escribir){var a=empleados.autorizarSalarios(escribir);empleados.autorizar(emp,true,false);return new MapSqlParameterSource("inst",a.institucionId()).addValue("actor",a.usuarioId()).addValue("emp",emp);}
 public Prestamo obtener(Long emp,Long id){return jdbc.query(SELECT+" WHERE p.id=:id AND p.empleado_id=:emp AND p.institucion_id=:inst",p(emp,false).addValue("id",id),MAP).stream().findFirst().orElseThrow(()->new AccessDeniedException("Préstamo no autorizado"));}
 public Page<Prestamo> listar(Long emp,FiltroPrestamoEmpleado original){var f=original.normalizado();var par=p(emp,false).addValue("estado",f.estadoPrestamo()).addValue("q",f.buscarPrestamo());String where=" WHERE p.empleado_id=:emp AND p.institucion_id=:inst AND (:estado='TODOS' OR p.estado=:estado) AND strpos(lower('PRE-'||lpad(p.id::text,6,'0')||' '||p.concepto_codigo||' '||p.concepto_nombre||' '||p.motivo),lower(:q))>0";long n=jdbc.queryForObject("SELECT count(*) FROM prestamo_empleado p"+where,par,Long.class);var pg=PageRequest.of(f.paginaPrestamo(),f.tamanioPrestamo());return new PageImpl<>(jdbc.query(SELECT+where+" ORDER BY p.id DESC LIMIT :limite OFFSET :offset",par.addValue("limite",pg.getPageSize()).addValue("offset",pg.getOffset()),MAP),pg,n);}
 public List<OpcionAutocompletado> conceptos(Long emp,String q){var par=p(emp,false);String t=OrganizacionLaboralService.texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre FROM concepto_nomina WHERE institucion_id=:inst AND activo AND naturaleza='DEDUCCION' AND aplicacion='CON_SALDO' AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY id LIMIT 11",par.addValue("q",t),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),"Préstamo sin intereses · Con saldo"));}
 public Concepto concepto(Long emp,Long id){p(emp,false);var c=conceptos.obtener(id);if(!c.activo()||!"DEDUCCION".equals(c.naturaleza())||!"CON_SALDO".equals(c.aplicacion()))throw regla("Selecciona una deducción activa de aplicación Con saldo en el catálogo.");return new Concepto(c.id(),c.codigo()+" · "+c.nombre(),c.version());}
 private void bloquear(Long emp){var par=p(emp,true);jdbc.queryForObject("SELECT id FROM empleado WHERE id=:emp AND institucion_id=:inst FOR UPDATE",par,Long.class);jdbc.query("SELECT empleado_id FROM empleado_laboral WHERE empleado_id=:emp FOR UPDATE",par,(r,n)->r.getLong(1));if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT activo FROM institucion WHERE id=:inst FOR SHARE",par,Boolean.class)))throw regla("La institución está inactiva; sólo consulta.");}
 private void elegible(Long emp,LocalDate inicio){var par=p(emp,true);if(inicio==null||inicio.getDayOfMonth()!=1||inicio.isBefore(empleados.hoyLaboral(emp).withDayOfMonth(1)))throw regla("Selecciona el primer día del mes actual o de un mes futuro para iniciar los descuentos.");
  long n=jdbc.queryForObject("SELECT count(*) FROM empleado e JOIN empleado_laboral l ON l.empleado_id=e.id JOIN empleado_calendario_nomina ec ON ec.empleado_id=e.id JOIN calendario_nomina c ON c.id=ec.calendario_id WHERE e.id=:emp AND e.institucion_id=:inst AND e.activo AND l.situacion='ACTIVO' AND l.fecha_ingreso IS NOT NULL AND l.fecha_ingreso<=:inicio AND (l.fecha_baja IS NULL OR l.fecha_baja>=:inicio) AND c.activo AND c.frecuencia='MENSUAL'",par.addValue("inicio",inicio),Long.class);
  if(n!=1)throw regla("Confirma actividad laboral, ingreso y calendario mensual activo del empleado, compatibles con el inicio del descuento.");
  if(jdbc.queryForObject("SELECT count(*) FROM nomina_borrador_empleado ne WHERE (EXISTS(SELECT 1 FROM nomina_aplicacion a WHERE a.borrador_id=ne.borrador_id AND a.revision=ne.revision) OR EXISTS(SELECT 1 FROM nomina_autorizacion a WHERE a.borrador_id=ne.borrador_id AND a.revision=ne.revision)) AND 1=1 AND ne.empleado_id=:emp AND ne.institucion_id=:inst AND ne.fecha_fin>=:inicio",par,Long.class)>0)throw regla("Hay una nómina aplicada o autorizada desde ese mes. Elige un primer descuento posterior; no se cambia lo pagado.");
 }
 public PrestamoEmpleadoForm formulario(Long emp,Long id){var r=obtener(emp,id);if(!r.estado().equals("BORRADOR"))throw regla("Sólo se edita el borrador sin entregar.");var f=new PrestamoEmpleadoForm();f.setConceptoId(r.conceptoId());f.setConceptoTexto(r.concepto());f.setConceptoVersion(r.conceptoVersion());f.setImporte(r.importe());f.setParcialidad(r.parcialidad());f.setPrimerDescuento(r.primerDescuento());f.setMotivo(r.motivo());f.setVersion(r.version());f.setSolicitud(r.solicitud());return f;}
 @Transactional public Long guardar(Long emp,Long id,PrestamoEmpleadoForm f){bloquear(emp);elegible(emp,f.getPrimerDescuento());validarDinero(f.getImporte());validarDinero(f.getParcialidad());motivo(f.getMotivo());if(f.getParcialidad().compareTo(f.getImporte())>0)throw regla("La parcialidad no puede superar el importe del préstamo.");if(f.getSolicitud()==null||f.getVersion()==null||f.getVersion()<0||f.getConceptoId()==null||f.getConceptoVersion()==null)throw regla("Selecciona un concepto y recarga el formulario antes de confirmar.");var par=p(emp,true).addValue("concepto",f.getConceptoId());jdbc.query("SELECT id FROM concepto_nomina WHERE id=:concepto AND institucion_id=:inst FOR SHARE",par,(r,n)->r.getLong(1));var c=concepto(emp,f.getConceptoId());if(!Objects.equals(c.version(),f.getConceptoVersion())||!Objects.equals(c.texto(),f.getConceptoTexto()))throw regla("El concepto cambió. Vuelve a seleccionarlo antes de guardar.");
  var cat=conceptos.obtener(c.id());par.addValue("codigo",cat.codigo()).addValue("nombre",cat.nombre()).addValue("conceptoVersion",c.version()).addValue("importe",f.getImporte()).addValue("cuota",f.getParcialidad()).addValue("inicio",f.getPrimerDescuento()).addValue("motivo",f.getMotivo().strip()).addValue("solicitud",f.getSolicitud()).addValue("version",f.getVersion());
  if(id==null){if(jdbc.queryForObject("SELECT count(*) FROM prestamo_empleado WHERE institucion_id=:inst AND solicitud=:solicitud",par,Long.class)>0)throw regla("Este formulario ya fue guardado. Vuelve al listado; no se duplicó el préstamo.");return jdbc.queryForObject("INSERT INTO prestamo_empleado(institucion_id,empleado_id,concepto_id,concepto_codigo,concepto_nombre,concepto_version,moneda,importe,parcialidad,primer_descuento,solicitud,motivo,motivo_operacion,creado_por_id,actualizado_por_id) SELECT :inst,:emp,:concepto,:codigo,:nombre,:conceptoVersion,moneda_predeterminada,:importe,:cuota,:inicio,:solicitud,:motivo,:motivo,:actor,:actor FROM institucion WHERE id=:inst RETURNING id",par,Long.class);}
  var r=obtener(emp,id);if(!r.estado().equals("BORRADOR")||!Objects.equals(r.version(),f.getVersion())||!r.solicitud().equals(f.getSolicitud()))throw regla("El préstamo cambió o ya fue entregado/cancelado. Recarga antes de continuar.");int n=jdbc.update("UPDATE prestamo_empleado SET concepto_id=:concepto,concepto_codigo=:codigo,concepto_nombre=:nombre,concepto_version=:conceptoVersion,importe=:importe,parcialidad=:cuota,primer_descuento=:inicio,motivo=:motivo,motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:inst AND empleado_id=:emp AND version=:version",par.addValue("id",id));if(n!=1)throw regla("El préstamo cambió; no se sobrescribió la captura.");return id;
 }
 @Transactional public void cancelar(Long emp,Long id,Long version,String razon){bloquear(emp);var r=obtener(emp,id);motivo(razon);if(!r.estado().equals("BORRADOR")||!Objects.equals(r.version(),version))throw regla("Sólo se cancela un borrador sin entregar y sin cambios. Una entrega real no se borra.");jdbc.update("UPDATE prestamo_empleado SET estado='CANCELADO',motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:inst AND empleado_id=:emp",p(emp,true).addValue("id",id).addValue("motivo",razon.strip()));}
 public boolean entregaHabilitada(){return entregaHabilitada;}
 public boolean puedeEntregar(){return entregaHabilitada&&empleados.permitido("CONDICION_SALARIAL_ADMINISTRAR")&&empleados.permitido("MOVIMIENTO_FINANCIERO_REGISTRAR");}
 private void financiero(Long emp){p(emp,true);if(!empleados.permitido("MOVIMIENTO_FINANCIERO_REGISTRAR"))throw new AccessDeniedException("Se requiere administración salarial y registro financiero para entregar préstamos");if(!entregaHabilitada)throw regla("Las entregas de préstamos están protegidas hasta habilitar pagos y abonos individuales en la fase 5. Puedes guardar y revisar borradores, sin mover dinero.");}
 private Cuenta cuenta(Long emp,Long id,String moneda){financiero(emp);return jdbc.query("SELECT c.id,c.codigo||' · '||c.nombre texto,c.moneda,c.version,coalesce((SELECT m.saldo_posterior FROM movimiento_financiero m WHERE m.cuenta_id=c.id ORDER BY m.secuencia_cuenta DESC LIMIT 1),c.saldo_inicial) saldo FROM cuenta_financiera c WHERE c.id=:cuenta AND c.institucion_id=:inst AND c.activo AND c.plantel_id IS NULL AND c.tipo IN ('CAJA','BANCO') AND c.moneda=:moneda",p(emp,true).addValue("cuenta",id).addValue("moneda",moneda),(r,n)->new Cuenta(r.getLong("id"),r.getString("texto"),r.getString("moneda"),r.getBigDecimal("saldo"),r.getLong("version"))).stream().findFirst().orElseThrow(()->regla("Selecciona caja o banco institucional activo, en la moneda del préstamo."));}
 public Revision revisar(Long emp,Long id,EntregarPrestamoForm f){financiero(emp);var r=obtener(emp,id);if(!r.estado().equals("BORRADOR")||!Objects.equals(r.version(),f.getVersion()))throw regla("El préstamo cambió o ya fue entregado/cancelado.");elegible(emp,r.primerDescuento());var c=cuenta(emp,f.getCuentaId(),r.moneda());if(c.saldo().compareTo(r.importe())<0)throw regla("La cuenta no tiene saldo suficiente para entregar este préstamo.");var ms=jdbc.queryForList("SELECT id,codigo,nombre,version FROM motivo_financiero WHERE id=:motivo AND institucion_id=:inst AND activo AND naturaleza IN ('EGRESO','AMBOS')",p(emp,true).addValue("motivo",f.getMotivoPagoId()));if(ms.isEmpty())throw regla("Selecciona un motivo financiero activo de egreso.");var m=ms.getFirst();motivo(f.getMotivo());if(f.getReferencia()==null||f.getReferencia().isBlank()||f.getReferencia().length()>150)throw regla("Captura referencia o comprobante de entrega, máximo150 caracteres.");String sello=PreparacionNominaService.sello(r+"|"+c+"|"+m+"|"+f.getReferencia().strip()+"|"+f.getMotivo().strip());return new Revision(r,c,m.get("codigo")+" · "+m.get("nombre"),c.saldo().subtract(r.importe()),sello);}
 @Transactional public Long entregar(Long emp,Long id,EntregarPrestamoForm f,String sello){financiero(emp);if(!f.isEntregaConfirmada())throw regla("Confirma la entrega real; no se envía una transferencia bancaria desde el sistema.");bloquear(emp);var r=obtener(emp,id);var par=p(emp,true).addValue("id",id).addValue("cuenta",f.getCuentaId()).addValue("motivoFin",f.getMotivoPagoId());jdbc.query("SELECT id FROM cuenta_financiera WHERE id=:cuenta AND institucion_id=:inst FOR UPDATE",par,(x,n)->x.getLong(1));jdbc.query("SELECT id FROM motivo_financiero WHERE id=:motivoFin AND institucion_id=:inst FOR SHARE",par,(x,n)->x.getLong(1));var v=revisar(emp,id,f);if(!Objects.equals(v.sello(),sello))throw regla("Cambió la cuenta, el saldo o la captura. Revisa nuevamente antes de entregar; no se movió dinero.");String zona=jdbc.queryForObject("SELECT zona_horaria FROM institucion WHERE id=:inst",par,String.class);var ahora=LocalDateTime.now(ZoneId.of(zona)).withSecond(0).withNano(0);
  var mov=movimientos.registrarPrestamo(new MovimientoManualRequest(empleados.autorizarSalarios(true).institucionId(),f.getCuentaId(),null,ahora,DireccionMovimiento.EGRESO,f.getMotivoPagoId(),r.importe(),"Entrega préstamo "+r.folio(),r.folio(),"Personal de la institución","PRESTAMO:"+id));
  var c=jdbc.queryForMap("SELECT codigo,nombre FROM cuenta_financiera WHERE id=:cuenta",par);jdbc.update("INSERT INTO prestamo_entrega(prestamo_id,institucion_id,empleado_id,movimiento_id,cuenta_codigo,cuenta_nombre,referencia,importe,moneda,usuario_id,motivo) VALUES(:id,:inst,:emp,:mov,:codigo,:nombre,:ref,:importe,:moneda,:actor,:motivo)",par.addValue("mov",mov.id()).addValue("codigo",c.get("codigo")).addValue("nombre",c.get("nombre")).addValue("ref",f.getReferencia().strip()).addValue("importe",r.importe()).addValue("moneda",r.moneda()).addValue("motivo",f.getMotivo().strip()));jdbc.update("UPDATE prestamo_empleado SET estado='ACTIVO',motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:inst AND empleado_id=:emp",par);return mov.id();
 }
 public List<OpcionAutocompletado> cuentas(Long emp,String q){financiero(emp);String t=OrganizacionLaboralService.texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre,moneda FROM cuenta_financiera WHERE institucion_id=:inst AND activo AND plantel_id IS NULL AND tipo IN ('CAJA','BANCO') AND moneda=(SELECT moneda_predeterminada FROM institucion WHERE id=:inst) AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY id LIMIT 11",p(emp,true).addValue("q",t),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),"Institucional · "+r.getString("moneda")));}
 public List<OpcionAutocompletado> motivos(Long emp,String q){financiero(emp);String t=OrganizacionLaboralService.texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre FROM motivo_financiero WHERE institucion_id=:inst AND activo AND naturaleza IN ('EGRESO','AMBOS') AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY id LIMIT 11",p(emp,true).addValue("q",t),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),"Egreso"));}
 public Entrega entrega(Long emp,Long id){obtener(emp,id);return jdbc.query("SELECT en.*,to_char(en.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username FROM prestamo_entrega en JOIN institucion i ON i.id=en.institucion_id JOIN usuario u ON u.id=en.usuario_id WHERE en.prestamo_id=:id AND en.empleado_id=:emp AND en.institucion_id=:inst",p(emp,false).addValue("id",id),(r,n)->new Entrega(r.getLong("movimiento_id"),r.getString("cuenta_codigo")+" · "+r.getString("cuenta_nombre"),r.getString("referencia"),r.getString("fecha"),r.getString("username"),r.getBigDecimal("importe"),r.getString("moneda"))).stream().findFirst().orElse(null);}
 public Page<Historia> historial(Long emp,Long id,int pagina){obtener(emp,id);var par=p(emp,false).addValue("id",id);var pg=PageRequest.of(Math.max(0,pagina),20);long n=jdbc.queryForObject("SELECT count(*) FROM prestamo_empleado_historial WHERE prestamo_id=:id AND institucion_id=:inst",par,Long.class);return new PageImpl<>(jdbc.query("SELECT to_char(h.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username,h.datos->'despues'->>'estado' estado,h.datos->'despues'->>'motivo_operacion' motivo FROM prestamo_empleado_historial h JOIN institucion i ON i.id=h.institucion_id JOIN usuario u ON u.id=h.usuario_id WHERE h.prestamo_id=:id AND h.institucion_id=:inst ORDER BY h.id DESC LIMIT 20 OFFSET :offset",par.addValue("offset",pg.getOffset()),(r,k)->new Historia(r.getString("fecha"),r.getString("username"),r.getString("estado"),r.getString("motivo"))),pg,n);}
 private static void validarDinero(BigDecimal x){if(x==null||x.signum()<=0||x.scale()>2||x.precision()-x.scale()>17)throw regla("Captura importes positivos con máximo dos decimales.");}
 private static void motivo(String m){if(m==null||m.isBlank()||m.length()>2000)throw regla("Captura un motivo de máximo2000 caracteres.");}
 private static ReglaNegocioException regla(String m){return new ReglaNegocioException(m);}
}
